import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * LEDGERX - a batch report over an INDEXED (VSAM) account file,
 * translated from COBOL 85. Idiomatic variant: modern Java structure over
 * literal transcription.
 *
 * The legacy program reads an INDEXED file with ACCESS MODE SEQUENTIAL,
 * so records arrive in RECORD KEY order - never the order they were
 * loaded (docs/vsam.md, measured against GnuCOBOL). The harness gives
 * both sides the same logical record set as fixed-width record images, so
 * this translation models the index rather than the seed:
 *
 *   - ascending key order means the first record read carries the LOWEST
 *     RECORD KEY and the last carries the HIGHEST, so WS-FIRST / WS-LAST
 *     are the minimum and maximum keys - independent of seed order;
 *   - a duplicate RECORD KEY is rejected by the file system on WRITE
 *     (status 22) and the first occurrence survives, so a repeated key is
 *     counted once.
 *
 * COUNT/TOTAL/FEE are order-independent, so a translation that walks the
 * seed in the order given still gets those right - the ordering error
 * surfaces only in FIRST/LAST.
 */
public final class Ledgerx {

    /** ADD 1: one increment per record. */
    private static final BigDecimal ONE = new BigDecimal("1");
    /** COMPUTE WS-FEE ROUNDED = WS-TOTAL * 15 / 1000. */
    private static final BigDecimal FEE_RATE = new BigDecimal("15");
    private static final BigDecimal THOUSAND = new BigDecimal("1000");
    /** IF WS-TOTAL > 5000.00. */
    private static final BigDecimal TIER_LIMIT = new BigDecimal("5000.00");
    /** PIC 9(7)V99 capacity (WS-TOTAL). */
    private static final BigDecimal PIC_9_7_V99 = new BigDecimal("10000000");
    /** PIC 9(5)V99 capacity (WS-FEE). */
    private static final BigDecimal PIC_9_5_V99 = new BigDecimal("100000");

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        BigDecimal count = BigDecimal.ZERO;   // WS-COUNT PIC 9(3)    VALUE ZERO
        BigDecimal total = BigDecimal.ZERO;   // WS-TOTAL PIC 9(7)V99 VALUE ZERO
        String first = "     ";               // WS-FIRST PIC X(5) VALUE SPACES
        String last = "     ";                // WS-LAST  PIC X(5) VALUE SPACES

        // PERFORM READ-LOOP UNTIL WS-EOF = "Y": one record per line, the
        // single read site mirroring the single COBOL READ.
        List<String> written = new ArrayList<>();
        String line;
        while ((line = in.readLine()) != null) {
            if (!line.trim().isEmpty()) {
                String key = keyOf(line);           // AC-ID  PIC X(5)
                BigDecimal balance = balanceOf(line); // AC-BAL PIC 9(5)V99
                // The keyed file rejects a duplicate RECORD KEY (status 22);
                // the first occurrence is the one that survives.
                if (!alreadyWritten(written, key)) {
                    written.add(key);
                    count = count.add(ONE);
                    total = total.add(balance).remainder(PIC_9_7_V99);
                    // Record the first and last account seen.
                    if (first.equals("     ")) {
                        first = key;
                    }
                    last = key;
                }
            }
        }

        BigDecimal fee = total.multiply(FEE_RATE).divide(THOUSAND)
                .setScale(2, RoundingMode.HALF_UP)
                .remainder(PIC_9_5_V99);
        String tier = total.compareTo(TIER_LIMIT) > 0 ? "GOLD" : "STD ";

        StringBuilder out = new StringBuilder();
        out.append("COUNT=").append(count.toPlainString()).append('\n');
        out.append("TOTAL=").append(total.setScale(2, RoundingMode.DOWN).toPlainString()).append('\n');
        out.append("FEE=").append(fee.setScale(2, RoundingMode.DOWN).toPlainString()).append('\n');
        out.append("FIRST=").append(first).append('\n');
        out.append("LAST=").append(last).append('\n');
        out.append("TIER=").append(tier).append('\n');
        System.out.print(out);
    }

    /** Decode AC-ID (PIC X(5)) out of its fixed byte slice 0..5. */
    private static String keyOf(String rec) {
        return rec.substring(0, 5);
    }

    /**
     * Decode AC-BAL (PIC 9(5)V99) out of its fixed byte slice 5..12. The
     * seven digits carry an implied decimal point at scale 2, applied with
     * movePointLeft.
